SELECT





            AND u.vehicle_id = #{query.vehicleId}


            AND u.applicant_id = #{query.applicantId}


            AND u.status = #{query.status}


    AND u.del_flag = '0'

ORDER BY u.create_time DESC, u.usage_id DESC

SELECT


WHERE u.vehicle_id = #{vehicleId}
  AND u.del_flag = '0'
ORDER BY u.create_time DESC, u.usage_id DESC
LIMIT ${limit}

SELECT u.usage_id, u.vehicle_id, v.license_plate AS vehicle_plate, u.status, CASE WHEN u.status = '3' THEN '3' WHEN u.status IN ('0','1') THEN '2' ELSE u.status END AS runtime_status, COALESCE(app.nick_name, app.user_name) AS applicant_name, COALESCE(drv.nick_name, drv.user_name) AS driver_name, u.destination, u.start_time, u.end_time, u.actual_start_time, u.actual_end_time FROM sys_vehicle_usage u LEFT JOIN sys_vehicle v ON v.vehicle_id = u.vehicle_id LEFT JOIN sys_user app ON app.user_id = u.applicant_id AND app.del_flag = '0' LEFT JOIN sys_user drv ON drv.user_id = u.driver_id AND drv.del_flag = '0' WHERE u.del_flag = '0'
AND u.vehicle_id = #{vehicleId}
AND u.end_time >= #{startDate}
AND u.start_time <= #{endDate}
ORDER BY u.start_time ASC, u.usage_id ASC
